public class Main {
    static int contarPares(int[] nums) {
        int total = 0;
        for (int n : nums) {
            if (n % 2 == 0) total++;
        }
        return total;
    }

    public static void main(String[] args) {
        System.out.println(contarPares(new int[]{1, 2, 3, 4, 6}));
        System.out.println(contarPares(new int[]{}));
        System.out.println(contarPares(new int[]{7, 9}));
    }
}

